{"cmd": "cd /workspace/target && python3 -c "
import pandas as pd,numpy as np
tx=pd.read_parquet('data/transactions.parquet')
c=tx[tx.is_credit]; o=tx[~tx.is_credit]
# for each credit, look at prior order lines same cust+sku: does qty match exactly?
om={}
for cid,sku,dt,q in zip(o.customer_id,o.StockCode,o.InvoiceDate,o.Quantity):
    om.setdefault((cid,sku),[]).append((dt,q))
for k in om: om[k].sort()
exact=0;anyprior=0;tot=0
for cid,sku,dt,q in zip(c.customer_id,c.StockCode,c.InvoiceDate,c.Quantity):
    tot+=1
    pri=[x for x in om.get((cid,sku),[]) if x[0]<dt]
    if pri:
        anyprior+=1
        if any(x[1]==-q for x in pri): exact+=1
print('credits',tot,'with prior',anyprior,'exact qty match among prior',exact)
""}

